import os
import random
import numpy as np
import torch


class Config:
    """
    Global configuration for the Hotel ID project.
    """

    # ==========================================
    # Path Configuration
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_1"
    SUBMISSION_DIR = "./submission"

    # Image Directories
    TRAIN_IMAGES_DIR = os.path.join(INPUT_DIR, "train_images")
    TEST_IMAGES_DIR = os.path.join(INPUT_DIR, "test_images")

    # Metadata Paths (Generated by metadata script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Output Paths
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_CHECKPOINT_DIR = WORKING_DIR
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # ==========================================
    # Data Configuration
    # ==========================================
    IMAGE_SIZE = 224
    CHANNELS = 3
    NUM_CLASSES = 7770  # Total unique hotels in training set
    NUM_WORKERS = 8  # Optimized for 12 vCPUs

    # ==========================================
    # Model Configuration
    # ==========================================
    MODEL_NAME = "resnet18"
    PRETRAINED = True
    TOP_K = 5  # For MAP@5 evaluation and submission

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 256  # A100 40GB allows for larger batch sizes with ResNet18
    EPOCHS = 10
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-4
    PATIENCE = 3  # Early stopping patience

    # ==========================================
    # Debugging / Development
    # ==========================================
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 2000  # Number of samples to use when DEBUG is True

    # ==========================================
    # Hardware
    # ==========================================
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @classmethod
    def print_config(cls):
        """Prints the current configuration."""
        print("=" * 30)
        print("Configuration:")
        for key, value in cls.__dict__.items():
            if not key.startswith("__") and not callable(value):
                print(f"{key}: {value}")
        print("=" * 30)


def seed_everything(seed=Config.SEED):
    """
    Sets the random seed for reproducibility across Python, NumPy, and PyTorch.

    Args:
        seed (int): The seed value to use.
    """
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False


def setup_directories(
    working_dir=Config.WORKING_DIR, submission_dir=Config.SUBMISSION_DIR
):
    """
    Creates necessary working and submission directories.

    Args:
        working_dir (str): Path to the working directory.
        submission_dir (str): Path to the submission directory.
    """
    os.makedirs(working_dir, exist_ok=True)
    os.makedirs(submission_dir, exist_ok=True)
